import { QueryKeys } from '@/constants/query-keys';
import { getActiveEsteiraId } from '@/functions/broker/verifyActiveEsteira';
import {
    useCedenteLinkedEsteirasQuery,
    useExtratoCedenteDataQuery,
} from '@/hooks/queries/cedentes';
import { useExtratoDataQueryOptions } from '@/hooks/queries/extrato';
import { useEsteiraDocumentoUpdates } from '@/hooks/useEsteiraDocumentoUpdates';
import {
    getDocsFromEsteira,
    getEsteiraExigenciasCondicionais,
    type EsteiraExigenciaCondicional,
} from '@/services/BrokerServices';
import { useBrokerStore } from '@/store/useBroker';
import { EsteiraDocs, LinkedCedenteEsteira } from '@/types/broker';
import { OficioEsteiraResumo } from '@/types/oficio';
import queryClient from '@/utils/queryClient';
import { useQuery } from '@tanstack/react-query';
import { createContext, useCallback, useContext, useMemo } from 'react';

type DocsSliderContextType = {
    // cedente
    cedenteType: 'PF' | 'PJ';

    // ids
    activeCedenteEsteiraId: number | null;
    activeRepresentanteEsteiraId: number | null;

    // esteiras
    oficioEsteirasAtivas: OficioEsteiraResumo[] | undefined;
    linkedEsteirasCedente: LinkedCedenteEsteira[] | undefined;
    linkedEsteirasRepresentante: LinkedCedenteEsteira[] | undefined;

    // docs
    esteiraDocsCedente: EsteiraDocs[] | undefined;
    esteiraDocsRepresentante: EsteiraDocs[] | undefined;
    exigenciasCondicionaisCedente: EsteiraExigenciaCondicional[];

    // ui states
    uiStates: {
        isLoadingLinkedEsteirasCedente: boolean;
        isLoadingLinkedEsteirasRepresentante: boolean;
        isLoadingEsteiraDocsCedente: boolean;
        isLoadingEsteiraDocsRepresentante: boolean;
    };
};

const DocsSliderContext = createContext<DocsSliderContextType | undefined>(undefined);

export function DocsSliderContextProvider({ children }: { children: React.ReactNode }) {
    const activeCedenteId = useBrokerStore((store) => store.activeCedente?.id);
    const activeCedenteType = useBrokerStore((store) => store.activeCedente?.tipo);
    const extratoId = useBrokerStore((store) => store.extratoId);

    // ==================
    // # React Query Hooks
    // ==================
    const { data: cedenteData } = useExtratoCedenteDataQuery(activeCedenteId);
    const { data: detailsExtratoData } = useQuery(useExtratoDataQueryOptions(extratoId));

    // Constants needing early definition
    const oficioEsteirasAtivas = detailsExtratoData?.esteira_documentos_por_cedente;

    const { data: linkedEsteirasCedente, isLoading: isLoadingLinkedEsteirasCedente } =
        useCedenteLinkedEsteirasQuery(activeCedenteId);

    const { data: linkedEsteirasRepresentante, isLoading: isLoadingLinkedEsteirasRepresentante } =
        useCedenteLinkedEsteirasQuery(cedenteData?.representante_legal?.id);

    // Computed Active Esteira IDs
    const activeCedenteEsteiraId = useMemo(
        () => getActiveEsteiraId(linkedEsteirasCedente, oficioEsteirasAtivas),
        [linkedEsteirasCedente, oficioEsteirasAtivas],
    );

    const activeRepresentanteEsteiraId = useMemo(
        () => getActiveEsteiraId(linkedEsteirasRepresentante, oficioEsteirasAtivas),
        [linkedEsteirasRepresentante, oficioEsteirasAtivas],
    );

    // Queries exclusivas desse componente para docs
    const { data: esteiraDocsCedente, isLoading: isLoadingEsteiraDocsCedente } = useQuery<
        EsteiraDocs[]
    >({
        queryKey: [
            QueryKeys.broker.details.cedenteDocsData,
            activeCedenteId,
            activeCedenteEsteiraId,
        ],
        queryFn: () => getDocsFromEsteira(activeCedenteEsteiraId!),
        enabled: !!linkedEsteirasCedente?.length && !!activeCedenteEsteiraId,
    });

    const { data: esteiraDocsRepresentante, isLoading: isLoadingEsteiraDocsRepresentante } =
        useQuery<EsteiraDocs[]>({
            queryKey: [
                QueryKeys.broker.details.representateDocsData,
                cedenteData?.representante_legal?.id,
                activeRepresentanteEsteiraId,
            ],
            queryFn: () => getDocsFromEsteira(activeRepresentanteEsteiraId!),
            enabled: !!linkedEsteirasRepresentante?.length && !!activeRepresentanteEsteiraId,
        });

    const { data: exigenciasCondicionaisCedente = [] } = useQuery<EsteiraExigenciaCondicional[]>({
        queryKey: [
            QueryKeys.broker.details.cedenteExigenciasCondicionais,
            activeCedenteId,
            activeCedenteEsteiraId,
        ],
        queryFn: () => getEsteiraExigenciasCondicionais(activeCedenteEsteiraId!),
        enabled: !!linkedEsteirasCedente?.length && !!activeCedenteEsteiraId,
    });

    // ==================
    // # Constants
    // ==================
    const cedenteType = useMemo(() => {
        if (activeCedenteType === 'PJ' || activeCedenteType === 'PF') return activeCedenteType;
        return cedenteData?.cnpj ? 'PJ' : 'PF';

