'use client';

import { NEXO_FETCH_CONCURRENCY } from '@/constants/nexo-integration';
import { QueryKeys } from '@/constants/query-keys';
import { mapWithConcurrency } from '@/lib/async/map-with-concurrency';
import { getDocsFromEsteira } from '@/services/BrokerServices';
import type { EsteiraDocs } from '@/types/broker';
import { useQuery } from '@tanstack/react-query';

export function useOficioEsteiraDocuments(esteiraIds: number[], extratoId: string) {
    return useQuery<EsteiraDocs[]>({
        queryKey: [QueryKeys.broker.details.cedenteDocsData, 'nexo-folder', extratoId, esteiraIds],
        queryFn: async () => {
            const batches = await mapWithConcurrency(
                esteiraIds,
                NEXO_FETCH_CONCURRENCY,
                (id) => getDocsFromEsteira(id),
            );
            const seen = new Set<number>();
            return batches.flat().filter((doc) => {
                if (seen.has(doc.id)) return false;
                seen.add(doc.id);
                return true;
            });
        },
        enabled: esteiraIds.length > 0,
    });
}

