import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { Check, Download, Eye, Paperclip } from 'lucide-react';
import { sendToastMessage } from '@/functions/messages/toastMessage';
import { downloadFile } from '@/functions/downloadFile';
import ImgDocVisualizer from '@/components/Modals/BrokersDocs/ImgDocVizualizer';
import { PDFViewerModal } from '@/components/Modals/PDFViewerModal';
import { getLeadById } from '@/services/leads';
import {
    deleteDocument,
    getDocsFromEsteira,
    uploadDocumentToEsteira,
} from '@/services/BrokerServices';
import {
    dashboard2DocMatchesSlot,
    dashboard2MergeEsteiraApiDocsIntoDocsCedente,
    dashboard2ResolveDocumentoTipoForSlot,
    type Dashboard2DocsCedenteRow,
    type Dashboard2EsteiraDocRow,
} from './dashboard2-cedente-doc-map';

interface CedenteDocsSectionProps {
    esteiraId: number;
    isPj: boolean;
    leadId?: string;
    onDocsChange?: () => void;
}

const SLOTS_REP = [
